      "content": "{\"identity\":{\"module_id\":\"INSTR-013\",\"name\":\"Удаление файлов патчем\",\"version\":\"v1.0.0\",\"created\":\"2025-06-01\",\"layer\":3,\"type\":\"critical_instruction\"},\"meta\":{\"description\":\"Инструкции по безопасному удалению файлов через патчи. Удаление файлов с delete_file: true.\",\"status\":\"active\",\"priority\":\"critical\",\"tags\":[\"delete\",\"critical\",\"file\",\"безопасность\",\"удаление\"],\"resonance\":\"100%\"},\"content\":{\"basic_deletion\":{\"title\":\"🗑️ Удалить один файл\",\"via_file_path\":{\"title\":\"Через file_path (с расширением)\",\"example\":\"{\\\"file_path\\\": \\\"honeycombs/tasks/tasks/old_file.json\\\", \\\"delete_file\\\": true}\"},\"via_target_module\":{\"title\":\"Через target_module (без .json)\",\"example\":\"{\\\"target_module\\\": \\\"honeycombs/tasks/tasks/old_file\\\", \\\"delete_file\\\": true}\"},\"notes\":[\"delete_file: true требует только file_path или target_module\",\"Поля changes и content не нужны\",\"После удаления файл убирается из кэша ядра автоматически\"]},\"batch_deletion\":{\"title\":\"🗑️🗑️🗑️ Удалить несколько файлов за раз\",\"multipatch_example\":\"{\\\"patches\\\": [ { \\\"file_path\\\": \\\"honeycombs/tasks/tasks/old1.json\\\", \\\"delete_file\\\": true }, { \\\"file_path\\\": \\\"honeycombs/tasks/tasks/old2.json\\\", \\\"delete_file\\\": true }, { \\\"file_path\\\": \\\"honeycombs/tasks/meta/legacy.json\\\", \\\"delete_file\\\": true } ] }\"},\"replace_deletion\":{\"title\":\"🔄 Удалить файл и сразу создать новый (в одном батче)\",\"example\":\"{\\\"patches\\\": [ { \\\"file_path\\\": \\\"honeycombs/tasks/tasks/old.json\\\", \\\"delete_file\\\": true }, { \\\"target_module\\\": \\\"honeycombs/tasks/tasks/new\\\", \\\"content\\\": \\\"{ \\\\\\\"tasks\\\\\\\": [] }\\\" } ] }\"},\"critical_rules\":{\"title\":\"⚠️ Важные правила удаления\",\"folders_cannot_be_deleted\":{\"title\":\"Папки удалять нельзя напрямую\",\"explanation\":\"GitHub не имеет API для удаления папки. Чтобы убрать папку — удали все файлы внутри неё, папка исчезнет автоматически.\",\"example\":\"Чтобы удалить папку tasks/old_tasks/:\\n1. Удали tasks/old_tasks/file1.json\\n2. Удали tasks/old_tasks/file2.json\\n3. Папка tasks/old_tasks/ исчезнет автоматически\"},\"no_rollback_mechanism\":{\"title\":\"Откат только через историю GitHub\",\"explanation\":\"Все удаления фиксируются как коммиты GitHub. Для отката нужно использовать историю коммитов.\",\"recommendation\":\"Перед удалением критических файлов сделай backup через read_file и сохрани локально.\"},\"dependencies_check\":{\"title\":\"Проверь зависимости перед удалением\",\"questions\":[\"1. Другие файлы ссылаются на удаляемый файл?\",\"2. Удаление нарушит работу системы?\",\"3. Есть ли backup файла?\",\"4. Удаляемый файл действительно больше не нужен?\"]}},\"safety_checklist\":{\"title\":\"✅ Чеклист безопасности перед удалением\",\"items\":[\"[ ] Прочитал patch_delete.json (этот файл) перед удалением\",\"[ ] Проверил зависимости — другие файлы не ссылаются на удаляемый\",\"[ ] Сделал backup через read_file и сохранение локально\",\"[ ] Обсудил с Садовником — файл действительно можно удалить?\",\"[ ] Убедился, что удаляю файл, а не папку\",\"[ ] Для папок: удалю ВСЕ файлы внутри, а не саму папку\",\"[ ] Проверил, что есть история коммитов для возможного отката\"]},\"registry\":{\"version\":\"v1.0.0\",\"created\":\"2025-06-01\",\"status\":\"active\",\"notes\":\"Интеграция из patch-delete.md в структуру сот\"}}"
    },
